def carry_archive_flag(apps, schema_editor):
    """
    Archiving used to be the reserved tag "__archive__" inside Conversation.tags.
    Tags are going away, so move that one bit onto its own field before the
    column is dropped.
    """
    Conversation = apps.get_model("core", "Conversation")
    for cid, tags in Conversation.objects.values_list("id", "tags"):
        if isinstance(tags, list) and "__archive__" in tags:
            Conversation.objects.filter(id=cid).update(is_archived=True)


